const CACHE='nepocore-worksheets-v10';
const CORE=['./','./styles.css','./app.mjs','./ui.mjs','./core.mjs','./scientific-core.mjs','./form-behavior.mjs','./catalog.mjs','./fresh-data.mjs','./pro-data.mjs','./blog.mjs','./blog-index.mjs','./blog-content/sources.mjs','./views.mjs','./content.mjs','./info.mjs','./expansion-data.mjs','./collections-data.mjs','./collection-sources.mjs','./favicon.ico','./assets/favicon-96.png','./assets/icon-192.png','./manifest.webmanifest','./assets/fonts/manrope-latin.woff2','./assets/fonts/dm-sans-latin.woff2'];
self.addEventListener('install',ev=>{ev.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)));self.skipWaiting();});
self.addEventListener('activate',ev=>{ev.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nepocore-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',ev=>{const url=new URL(ev.request.url);if(ev.request.method!=='GET'||url.origin!==self.location.origin||/\.(zip|pdf)$/i.test(url.pathname))return;ev.respondWith(fetch(ev.request).then(r=>{if(r.ok&&(ev.request.mode==='navigate'||/\.(mjs|js|css|woff2|svg|png)$/.test(url.pathname)))caches.open(CACHE).then(c=>c.put(ev.request,r.clone()));return r;}).catch(()=>caches.match(ev.request,{ignoreSearch:true}).then(r=>r||(ev.request.mode==='navigate'?caches.match(new URL('./',self.location).href):null)).then(r=>r||new Response('This resource is not cached. Reconnect and try again.',{status:503}))));});
